\label{le:rank}

  	Let $L$ be a finite distributive lattice and $K$ is a cutting of $L$. The rank generating function of $L\boxplus K$ is
	\[
	R(L\boxplus K,x) =
	\begin{cases}
	R(L,x) + x^{h_L(\hat0_K)+1}R(K,x), & \text{if } \hat1_K = \hat1_L; \\
	R(K,x) + xR(L,x), & \text{if } \hat0_K = \hat0_L.
	\end{cases}
	\]

\label{prop:rec-R}
	For $n\ge 5$
	\[
	R_n(x) =
	\begin{cases}
	xR_{n-1}(x) + R_{n-2}(x), & \mbox{if } 2\nmid n, \\
	R_{n-1}(x) + x^2R_{n-2}(x), & \mbox{if } 2\mid n.
	\end{cases}
	\]

\label{prop:rec-AB}
	
	\[
	\begin{cases}
	A_m(x) = (1+x+x^2)A_{m-1}(x) - x^2A_{m-2}(x), & (m\ge 4), \\
	B_m(x) = (1+x+x^2)B_{m-1}(x) - x^2B_{m-2}(x), & (m\ge 2).
	\end{cases}
	\]

\label{th:rnk}
     \begin{multline*}
	    r_{2m,k} = \delta_{1,m}\delta_{0,k}+ \sum_{i=0}^{\lfloor \frac m2 \rfloor}(-1)^i\binom{m-i}{i} \binom{m-2i;3}{k-2i} -\sum_{i=0}^{\lfloor \frac{m-1}{2} \rfloor}(-1)^i\binom{m-i-1}{i}\binom{m-2i-1;3}{k-2i}\\
 +\sum_{i=0}^{\lfloor \frac{m-2}{2} \rfloor}(-1)^i\binom{m-i-2}{i}\binom{m-2i-2;3}{k-2i}.
     \end{multline*}
and
 \begin{multline*}
   r_{2m+1,k} = \sum_{i=0}^{\lfloor\frac{m}{2}\rfloor} (-1)^i \binom{m-i}{i}\left(\binom{m-2i;3}{k-2i}+ \binom{m-2i;3}{k-2i-1}\right) \\
     -\sum_{i=0}^{\lfloor\frac{m-1}{2} \rfloor} (-1)^i \binom{m-i-1}{i}\left(\binom{m-2i-1;3}{k-2i-1} +\binom{m-2i-1;3}{k-2i-2}\right).
 \end{multline*}

By the Proposition~\ref{prop:rec-q},
\begin{align*}
  Q_n(x) &= \sum_{k\ge 0}q_{n,k}x^k = \sum_{k\ge 0}(q_{n-1,k} + q_{n-2,k} + q_{n-2,k-1})x^k \\
  &= \sum_{k\ge 0}q_{n-1,k}x^k + \sum_{k\ge 0}q_{n-2,k}x^k + x\sum_{k\ge 0}q_{n-2,k-1}x^{k-1} \\
  &= Q_{n-1}(x) + (1+x)Q_{n-2}(x).
\end{align*}

\label{th:gf-H}
	The generating function of $H_n(x)$ is
	\begin{align*}
	\sum_{n=0}^\infty H_n(x) y^n &= \frac{1 +xy(1+y) +2xy^3(1+y) -x^2y^3(1+y)^2)}{1-xy^2(1+y)}\\
     &= -2y+xy+xy^2+\frac{1+2y}{1-xy^2(1+y)}.
    \end{align*}

\begin{align*}
  \frac{1+2y}{1-xy^2(1+y)}
  &= \sum_{j\ge 0}(1+y)^jx^jy^{2j} +2\sum_{j\ge 0}(1+y)^{j}x^{j}y^{2j+1}\\
  &= \sum_{j\ge 0}\sum_{n-2j=0}^{j} \binom{j}{n-2j}x^jy^n +2\sum_{j\ge 0}\sum_{n-2j-1=0}^{j} \binom{j}{n-2j-1}x^{j1}y^n\\
  &= \sum_{n\ge 0}\sum_{k=\lceil \frac n3\rceil}^{\lfloor \frac n2 \rfloor}\binom{k}{n-2k}x^ky^n +2\sum_{n\ge 0}\sum_{k =\lceil \frac{n-1}{3}\rceil}^{\lfloor \frac{n-1}{2} \rfloor}\binom{k}{n-2k-1}x^ky^n.
 \end{align*}
 The proof is completed.
